def render_loader():
    """À appeler une fois, tout en haut de app.py. Le CSS (theme.css) montre le voile seulement quand le script tourne."""
    with st.container(key="loader"):
        st.markdown('<div class="ld-title"><span class="ld-dot"></span>Les données arrivent...</div>', unsafe_allow_html=True)
        components.html(GAME, height=260)